import hmac
import hashlib
import json
import base64
import time
import os
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading

SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
SESSION_STORE = {}
USER_DB = {}
LOCK = threading.Lock()

def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)

def create_token(user_id: str, role: str, expires_in: int = 3600) -> str:
    header = {'alg': 'HS256', 'typ': 'JWT'}
    now = int(time.time())
    payload = {
        'sub': user_id,
        'role': role,
        'iat': now,
        'exp': now + expires_in,
        'jti': secrets.token_hex(16)
    }
    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f"{header_b64}.{payload_b64}".encode()
    signature = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
    sig_b64 = b64url_encode(signature)
    return f"{header_b64}.{payload_b64}.{sig_b64}"

def verify_token(token: str) -> dict:
    """Verify token signature and expiration. Returns payload or raises."""
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Invalid token format')

    header_b64, payload_b64, sig_b64 = parts

    try:
        header = json.loads(b64url_decode(header_b64))
    except (json.JSONDecodeError, Exception) as e:
        raise ValueError(f'Invalid header: {e}')

    # Validate algorithm
    alg = header.get('alg')
    if alg not in ('HS256', 'HS384', 'HS512'):
        raise ValueError(f'Unsupported algorithm: {alg}')

    hash_func = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512
    }[alg]

    # Verify signature
    signing_input = f"{header_b64}.{payload_b64}".encode()
    expected_sig = hmac.new(SECRET_KEY.encode(), signing_input, hash_func).digest()
    provided_sig = b64url_decode(sig_b64)

    if not hmac.compare_digest(expected_sig, provided_sig):
        raise ValueError('Invalid signature')

    try:
        payload = json.loads(b64url_decode(payload_b64))
    except (json.JSONDecodeError, Exception) as e:
        raise ValueError(f'Invalid payload: {e}')

    # Check expiration
    exp = payload.get('exp')
    if exp is not None:
        if time.time() > exp:
            raise ValueError('Token expired')

    return payload

def validate_session(session_id: str) -> dict:
    """Validate an active session."""
    with LOCK:
        session = SESSION_STORE.get(session_id)
        if not session:
            raise ValueError('Session not found')
        if session.get('revoked'):
            raise ValueError('Session revoked')
    # Check token validity
    token = session.get('token')
    if not token:
        raise ValueError('No token in session')
    return verify_token(token)

def create_session(user_id: str, role: str) -> str:
    token = create_token(user_id, role)
    session_id = secrets.token_urlsafe(32)
    with LOCK:
        SESSION_STORE[session_id] = {
            'token': token,
            'user_id': user_id,
            'created': time.time(),
            'revoked': False
        }
    return session_id

def revoke_session(session_id: str, requesting_user: str) -> bool:
    with LOCK:
        session = SESSION_STORE.get(session_id)
        if not session:
            return False
        # Only the session owner or admin can revoke
        if session['user_id'] != requesting_user:
            # Check if requester is admin
            requester_sessions = [
                s for s in SESSION_STORE.values()
                if s['user_id'] == requesting_user and not s.get('revoked')
            ]
            is_admin = False
            for s in requester_sessions:
                try:
                    payload = verify_token(s['token'])
                    if payload.get('role') == 'admin':
                        is_admin = True
                        break
                except ValueError:
                    continue
            if not is_admin:
                return False
        session['revoked'] = True
    return True

def get_admin_data(payload: dict) -> dict:
    """Return sensitive admin data if authorized."""
    role = payload.get('role', '')
    if role == 'admin':
        return {
            'users': list(USER_DB.keys()),
            'sessions': len(SESSION_STORE),
            'secret_config': 'database_password=hunter2'
        }
    raise PermissionError('Admin access required')

class TokenHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 10240:
            self.send_error(413)
            return
        body = self.rfile.read(content_length)

        try:
            data = json.loads(body) if body else {}
        except json.JSONDecodeError:
            self.send_error(400)
            return

        if path == '/auth/login':
            username = data.get('username', '')
            password = data.get('password', '')
            if not username or not password:
                self._respond(400, {'error': 'Missing credentials'})
                return
            user = USER_DB.get(username)
            if not user:
                # Constant-time comparison to prevent timing attacks
                hmac.compare_digest(password, 'dummy_password_for_timing')
                self._respond(401, {'error': 'Invalid credentials'})
                return
            if not hmac.compare_digest(password, user['password']):
                self._respond(401, {'error': 'Invalid credentials'})
                return
            session_id = create_session(username, user.get('role', 'user'))
            self._respond(200, {'session_id': session_id})

        elif path == '/auth/register':
            username = data.get('username', '')
            password = data.get('password', '')
            if not username or not password or len(username) > 64:
                self._respond(400, {'error': 'Invalid input'})
                return
            if username in USER_DB:
                self._respond(409, {'error': 'User exists'})
                return
            USER_DB[username] = {'password': password, 'role': 'user'}
            self._respond(201, {'status': 'created'})

        elif path == '/auth/verify':
            token = data.get('token', '')
            try:
                payload = verify_token(token)
                self._respond(200, {'valid': True, 'payload': payload})
            except ValueError as e:
                self._respond(401, {'valid': False, 'error': str(e)})

        elif path == '/admin/data':
            session_id = self.headers.get('X-Session-ID', '')
            try:
                payload = validate_session(session_id)
                admin_data = get_admin_data(payload)
                self._respond(200, admin_data)
            except (ValueError, PermissionError) as e:
                self._respond(403, {'error': str(e)})
        else:
            self.send_error(404)

    def _respond(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        pass  # Suppress logs

if __name__ == '__main__':
    # Initialize admin user
    USER_DB['admin'] = {'password': os.environ.get('ADMIN_PASS', 'changeme'), 'role': 'admin'}
    server = HTTPServer(('127.0.0.1', 8080), TokenHandler)
    server.serve_forever()
